package app.noir.mobile;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.io.File;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

public final class HistoryPlusTest {
 Context isolated(){Context real=InstrumentationRegistry.getInstrumentation().getTargetContext();File dir=new File(real.getFilesDir(),"history-plus-"+UUID.randomUUID());dir.mkdirs();return new ContextWrapper(real){@Override public Context getApplicationContext(){return this;}@Override public File getFilesDir(){return dir;}};}
 JSONObject episode(String id,int number)throws Exception{return new JSONObject().put("id",id).put("group","show").put("title","Show").put("season",1).put("episode",number);}
 @Test public void choosingAnExistingFavoriteSwapsWithoutLosingAnotherTitle(){assertEquals(Arrays.asList("c","b","a","d"),PhoneTracker.replaceFavorite(Arrays.asList("a","b","c","d"),0,"c"));assertEquals(Arrays.asList("b","c","a"),PhoneTracker.replaceFavorite(Arrays.asList("a","b","c"),3,"a"));assertEquals(Arrays.asList("a","new","c","d"),PhoneTracker.replaceFavorite(Arrays.asList("a","b","c","d"),1,"new"));}
 @Test public void halfStarsRemainCompatible()throws Exception{assertEquals(8,DataStore.rating10(new JSONObject().put("review",new JSONObject().put("rating",4))));assertEquals(7,DataStore.rating10(new JSONObject().put("review",new JSONObject().put("rating",4).put("rating10",7))));DataStore data=new DataStore(isolated());try{data.rememberPhoneItem(episode("one",1));data.review10("one",7,"optional");JSONObject review=data.item("one").getJSONObject("review");assertEquals(7,review.getInt("rating10"));assertEquals(4,review.getInt("rating"));data.review("one",3,"old phone");assertEquals(6,DataStore.rating10(data.item("one")));}finally{data.network.shutdownNow();data.images.shutdownNow();}}
 @Test public void socialFieldsPersistOfflineAndRejectInvalidMoods()throws Exception{Context context=isolated();DataStore data=new DataStore(context);try{data.rememberPhoneItem(episode("one",1));data.favorites(Arrays.asList("show","movie","show","third","fourth","fifth"));assertEquals(4,data.favorites().length());assertEquals("movie",data.favorites().getString(1));data.like("show",true);data.seasonRating("show",1,9);data.reaction("one","wow");data.reaction("one","invalid");data.flush();DataStore restored=new DataStore(context);try{assertTrue(restored.liked("show"));assertEquals(9,restored.seasonRating("show",1));assertEquals("wow",restored.reaction("one"));assertEquals(4,restored.favorites().length());restored.like("show",false);assertFalse(restored.liked("show"));}finally{restored.network.shutdownNow();restored.images.shutdownNow();}}finally{data.network.shutdownNow();data.images.shutdownNow();}}
 @Test public void fieldClocksIgnoreOlderValuesAndUnknownKinds()throws Exception{JSONObject library=new JSONObject();DataStore.applyHistory(library,new JSONObject().put("kind","like").put("group","show").put("value",true).put("at",20));DataStore.applyHistory(library,new JSONObject().put("kind","like").put("group","show").put("value",false).put("at",10));assertEquals("show",library.getJSONArray("likes").getString(0));String before=library.toString();DataStore.applyHistory(library,new JSONObject().put("kind","future-kind").put("at",99));assertEquals(before,library.toString());}
 @Test public void identityAndPacingAreNeutral(){assertEquals("A new chapter",YearStoryActivity.identity(0,0,0,0,0));assertEquals("Night-owl binger",YearStoryActivity.identity(10,4,6,8,2));assertEquals("Weekend cinephile",YearStoryActivity.identity(10,1,6,8,2));assertEquals("Cinema explorer",YearStoryActivity.identity(10,1,1,8,2));assertEquals("Series storyteller",YearStoryActivity.identity(10,1,1,2,8));boolean previous=Loc.arabic;try{Loc.arabic=false;assertEquals("On pace for 365 this year",PhoneRewards.pacing(1,LocalDate.of(2025,1,1)));assertFalse(PhoneRewards.pacing(0,LocalDate.of(2026,10,24)).contains("behind"));}finally{Loc.arabic=previous;}}
 @Test public void widgetFindsNextEpisodeWithoutMutatingSharedItems()throws Exception{DataStore data=new DataStore(isolated());try{data.rememberPhoneItem(episode("one",1));data.rememberPhoneItem(episode("two",2));assertNull(NextUpWidget.next(data));data.mark("one",true,System.currentTimeMillis(),false);String snapshot=data.itemsShared().toString();assertEquals("two",NextUpWidget.next(data).optString("id"));assertEquals(snapshot,data.itemsShared().toString());}finally{data.network.shutdownNow();data.images.shutdownNow();}}
}
